use std::io::{self, BufRead, Write};

trait Pricing {
    fn total(&self, qty: i64, unit: i64) -> i64;
}

struct Plain;
struct Bulk;
struct Member;

impl Pricing for Plain {
    fn total(&self, qty: i64, unit: i64) -> i64 {
        qty * unit
    }
}

impl Pricing for Bulk {
    fn total(&self, qty: i64, unit: i64) -> i64 {
        let gross = qty * unit;
        if qty >= 10 {
            gross - gross / 10
        } else {
            gross
        }
    }
}

impl Pricing for Member {
    fn total(&self, qty: i64, unit: i64) -> i64 {
        let gross = qty * unit;
        let mut t = gross - gross * 5 / 100;
        if qty >= 3 {
            t -= 100;
        }
        t.max(0)
    }
}

fn format_cents(c: i64) -> String {
    format!("${}.{:02}", c / 100, c % 100)
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    let mut grand: i64 = 0;

    for line in stdin.lock().lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => break,
        };
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.is_empty() {
            continue;
        }
        if parts.len() < 4 {
            continue;
        }
        let name = parts[0];
        let qty: i64 = match parts[1].parse() {
            Ok(v) => v,
            Err(_) => continue,
        };
        let unit: i64 = match parts[2].parse() {
            Ok(v) => v,
            Err(_) => continue,
        };
        let strategy: Option<Box<dyn Pricing>> = match parts[3] {
            "plain" => Some(Box::new(Plain)),
            "bulk" => Some(Box::new(Bulk)),
            "member" => Some(Box::new(Member)),
            _ => None,
        };
        match strategy {
            Some(s) => {
                let t = s.total(qty, unit);
                grand += t;
                writeln!(out, "{} {}", name, format_cents(t)).unwrap();
            }
            None => {
                writeln!(out, "{} invalid kind", name).unwrap();
            }
        }
    }

    writeln!(out, "total {}", format_cents(grand)).unwrap();
}
